 const normalize=([x,y,z])=>[x/93,(y+18)/93,(z-15)/93];
 const regionCentres=[[40,48,2],[35,16,48],[50,-20,36],[34,-75,20],[43,-45,-24],[-37,42,4],[-32,10,50],[-46,-20,35],[-32,-70,15],[-39,-35,-25]].map(normalize);
