  const rotation=camera();paintCortex(rotation);
  for(let i=beads.length-1;i>=0;i--){const b=beads[i],t=(time-b.start)/850;if(t>=1||reduced.matches){b.el.remove();beads.splice(i,1);continue;}const end=project(growth[b.region].position,rotation);b.el.setAttribute('cx',b.entry[0]+(end[0]-b.entry[0])*ease(t));b.el.setAttribute('cy',b.entry[1]+(end[1]-b.entry[1])*ease(t));b.el.setAttribute('opacity',String((1-t)*.65));}
