 function drawInputs(){
  const loop=brands.length*900,travel=6300;
  inputTiles.forEach((tile,i)=>{const far=i>=brands.length;if(far&&(!state.depth||reduced.matches)){tile.style.opacity=0;return;}
   const t=((time+(i%brands.length)*900+(far?350:0)+1200)%loop)/travel,lane=signalLanes[i%brands.length];
   if(t>1&&!reduced.matches){tile.style.opacity=0;return;}
   if(!far&&!reduced.matches){const previous=phases.get(i);if(previous!==undefined&&previous<.91&&t>=.91)receive(i);phases.set(i,t);}
   const startY=cy+lane*(mobile?125:165),endX=cx-engine.offsetWidth*.42,endY=cy+lane*engine.offsetHeight*.13;let x,y,scale,opacity;
   if(reduced.matches){x=18+(i%2)*Math.max(38,(endX-42)/2);y=45+Math.floor(i/2)*(mobile?37:53);scale=.79;opacity=1;}
   else{x=curve(t,-35,endX*.25,endX-35,endX);y=curve(t,startY,startY,endY,endY);scale=(far?.78:1)*(1-.75*ease(clamp((t-.79)/.21)));opacity=Math.min(1,t*10)*(1-ease(clamp((t-.86)/.14)))*(far?.26:1);}
   const size=far?34:44;tile.style.transform=`translate(${x-size/2}px,${y-size/2}px) rotate(${reduced.matches?0:Math.sin(i+t*4)*7*(1-t)}deg) scale(${scale})`;tile.style.opacity=String(opacity);
  });
 }
 function drawDelivery(){const t=(time-deliveryStart)/800;if(t>=0&&t<=1&&!reduced.matches){const p=line.getPointAtLength(lineLength*t);delivery.setAttribute('cx',p.x);delivery.setAttribute('cy',p.y);delivery.setAttribute('opacity',Math.min(1,t*8,(1-t)*8));if(t>.9&&flashes[deliveryAction]<deliveryStart){flashes[deliveryAction]=time;}}else delivery.setAttribute('opacity',0);root.querySelectorAll('[data-flash]').forEach((el,i)=>el.style.opacity=String(reduced.matches?0:clamp(1-(time-flashes[i])/1100)));}
